39		httpClient := cfg.HTTP
40		if httpClient == nil {
41			timeout := cfg.Timeout
42			if timeout <= 0 {
43				timeout = defaultCloudHTTPTimeout
44			}
45			httpClient = &http.Client{Timeout: timeout}
46		} else if cfg.Timeout > 0 && httpClient.Timeout == 0 {
47			httpClient.Timeout = cfg.Timeout
48		}
