99	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
100		floored := since.Truncate(time.Minute)
101		ceiled := until.Truncate(time.Minute)
102		if !until.Equal(ceiled) {
103			ceiled = ceiled.Add(time.Minute)
104		}
105		return floored, ceiled
106	}
