108	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
109		if len(repoPaths) == 0 {
110			repoRoot, err := paths.WorktreeRoot(ctx)
111			if err != nil {
112				return nil, fmt.Errorf("not in a git repository: %w", err)
113			}
114			return []string{repoRoot}, nil
115		}
116	
117		roots := make([]string, 0, len(repoPaths))
118		for _, repoPath := range repoPaths {
119			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
120			output, err := cmd.Output()
121			if err != nil {
122				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
123			}
124			roots = append(roots, strings.TrimSpace(string(output)))
125		}
126		return roots, nil
127	}
