314	// branchLocalRevRange returns a git log rev range that limits commits to
315	// those unique to the current branch — reachable from HEAD but not from the
316	// repository's default branch. Falls back to "HEAD" when no default branch
317	// can be resolved (e.g. a fresh repo with no main/master ref).
318	func branchLocalRevRange(ctx context.Context, repoRoot string) string {
319		base := defaultBranchRef(ctx, repoRoot)
320		if base == "" {
321			return "HEAD"
322		}
323		return base + "..HEAD"
324	}
325	
326	// defaultBranchRef resolves the repository's default branch, preferring
327	// origin/HEAD and falling back to the conventional main/master names. Returns
328	// an empty string if nothing matches so callers can skip the exclusion.
329	func defaultBranchRef(ctx context.Context, repoRoot string) string {
330		if out, ok := runGitOutput(ctx, repoRoot, "symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"); ok {
331			ref := strings.TrimSpace(out)
332			if strings.HasPrefix(ref, "refs/remotes/") {
333				return strings.TrimPrefix(ref, "refs/remotes/")
334			}
335		}
336		for _, candidate := range []string{"origin/main", "origin/master", "main", "master"} {
337			if _, ok := runGitOutput(ctx, repoRoot, "rev-parse", "--verify", "--quiet", candidate); ok {
338				return candidate
339			}
340		}
341		return ""
342	}
