// resolveCheckpointShas returns a best-effort map from checkpoint ID to the
// git commit SHA that carries the matching Entire-Checkpoint trailer. Returns
// nil if no IDs are requested or the git command fails — callers fall back to
// the checkpoint IDs alone.
func resolveCheckpointShas(ctx context.Context, repoRoot string, ids []string) map[string]string {
	if len(ids) == 0 {
		return nil
	}
	wanted := make(map[string]struct{}, len(ids))
	for _, id := range ids {
		wanted[id] = struct{}{}
	}

	cmd := exec.CommandContext(
		ctx,
		"git",
		"-C",
		repoRoot,
		"log",
		"--all",
		"--grep",
		"Entire-Checkpoint:",
		"--format=%H %B%x00",
	)
	output, err := cmd.Output()
	if err != nil {
		return nil
	}

	result := make(map[string]string, len(ids))
	for _, record := range strings.Split(string(output), "\x00") {
		record = strings.TrimLeft(record, "\n")
		if record == "" {
			continue
		}
		sha, message, ok := strings.Cut(record, " ")
		if !ok {
			continue
		}
		for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
			id := checkpointID.String()
			if _, want := wanted[id]; !want {
				continue
			}
			if _, already := result[id]; !already {
				result[id] = sha
			}
		}
	}
	return result
}

