542	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
543		rootSet := map[string]struct{}{currentRepo: {}}
544		parent := filepath.Dir(currentRepo)
545	
546		entries, err := os.ReadDir(parent)
547		if err == nil {
548			candidates := make([]string, 0, len(entries))
549			for _, entry := range entries {
550				if !entry.IsDir() {
551					continue
552				}
553				candidate := filepath.Join(parent, entry.Name())
554				if _, statErr := os.Stat(filepath.Join(candidate, ".git")); statErr != nil {
555					continue
556				}
557				candidates = append(candidates, candidate)
558			}
559	
560			resolved := make([]string, len(candidates))
561			sem := make(chan struct{}, dispatchWizardRepoDiscoveryConcurrencyLimit)
562			var wg sync.WaitGroup
563			wg.Add(len(candidates))
564			for i, candidate := range candidates {
565				sem <- struct{}{}
566				go func(i int, candidate string) {
567					defer wg.Done()
568					defer func() { <-sem }()
569					if repoRoot, resolveErr := resolveDispatchWizardTopLevel(ctx, candidate); resolveErr == nil {
570						resolved[i] = repoRoot
571					}
572				}(i, candidate)
573			}
574			wg.Wait()
575			for _, repoRoot := range resolved {
576				if repoRoot != "" {
577					rootSet[repoRoot] = struct{}{}
578				}
579			}
580		}
581	
582		repoRoots := make([]string, 0, len(rootSet))
583		for repoRoot := range rootSet {
584			repoRoots = append(repoRoots, repoRoot)
585		}
586		sort.Slice(repoRoots, func(i, j int) bool {
587			if repoRoots[i] == currentRepo {
588				return true
589			}
590			if repoRoots[j] == currentRepo {
591				return false
592			}
593			return filepath.Base(repoRoots[i]) < filepath.Base(repoRoots[j])
594		})
595		return repoRoots
596	}
